import math

def solution(input_str):
    lines = input_str.strip().split('\n')
    n, m = map(int, lines[0].split())

    operations = []
    for i in range(1, n + 1):
        parts = lines[i].split()
        t_i, x_prime, y_i = int(parts[0]), int(parts[1]), int(parts[2])
        x_i = x_prime / 100000.0
        operations.append((t_i, x_i, y_i))

    # Track the earliest time-step to reach each banana count (1 to m)
    answer = [-1] * (m + 1)

    # Use a set for reachable counts at current step
    reachable = {0}  # Initially 0 bananas

    for step in range(n):
        t_i, x_i, y_i = operations[step]

        new_reachable = set()

        # Try each possible a_i from 0 to y_i
        for a_i in range(y_i + 1):
            for k in reachable:
                if k > m:
                    continue

                if t_i == 1:
                    # Type 1: apply k := ceil(k + x_i) a_i times
                    # This is equivalent to: ceil(k + a_i * x_i)
                    final_k = k + a_i * x_i
                    final_k = math.ceil(final_k)

                    if 0 <= final_k <= m:
                        if answer[final_k] == -1:
                            answer[final_k] = step + 1
                        new_reachable.add(final_k)

                else:
                    # Type 2: apply k := ceil(k * x_i) a_i times
                    # Need to apply sequentially
                    temp_k = k
                    applyable = True

                    for rep in range(a_i):
                        new_temp = temp_k * x_i
                        temp_k = math.ceil(new_temp)

                        if temp_k > m:
                            # If we exceed m in intermediate step, continue (might come back?)
                            # Actually since x_i >= 1 for both types, value only increases
                            if temp_k > m:
                                # Can't continue applying if exceeds m
                                temp_k = m  # Cap it
                            break

                    if 0 <= temp_k <= m:
                        if answer[temp_k] == -1:
                            answer[temp_k] = step + 1
                        new_reachable.add(temp_k)

        reachable = new_reachable

    return ' '.join(str(answer[i]) for i in range(1, m + 1))

