    # Find max team
    num_teams = max(max(wl) for wl in wish_list) if wish_list else 0

    # Assign trainer to team (cyclically distribute to both conferences)
    trainer_team = [0] * (n + 1)
    for t in range(1, n + 1):
        trainer_team[t] = wish_list[t-1][(t-1) % len(wish_list[t-1])]

    # Build team -> trainers on this team
    trainers_per_team = {}
    for t in range(1, n + 1):
        wt = trainer_team[t]
        if wt not in trainers_per_team:
            trainers_per_team[wt] = []
        trainers_per_team[wt].append(t)

    # Build team-hate between teams
    team_hate = {}
    for u, v in hate:
        tu, tv = trainer_team[u], trainer_team[v]
        if tu != tv:
            if tu not in team_hate:
                team_hate[tu] = set()
            if tv not in team_hate:
                team_hate[tv] = set()
            team_hate[tu].add(tv)

    # Now assign teams to conferences
    team_conf = [0] * (num_teams + 1)

    # Greedy: if team has no hate partners, assign randomly
    # If it has hate partners, assign to minimize conflicts with same conference

    for t in range(1, num_teams + 1):
        if t not in team_hate:
            team_conf[t] = 2
        else:
            # Count neighbors in conf 1 vs conf 2
            same_1 = 0
            same_2 = 0
            for neighbor in team_hate[t]:
