                    elif team_conf[neighbor] == 2:
                        same_2 += 1

            # Assign to create cross-conference hate with more existing assignments
            if same_1 >= same_2:
                team_conf[t] = 2
            else:
                team_conf[t] = 1

    return ' '.join(map(str, trainer_team[1:])) + '\n' + ' '.join(map(str, team_conf[1:num_teams+1]))

# Solution code for computing f_n using matrix exponentiation

def solution(input_str):
    n, f1, f2, f3, c = map(int, input_str.split())

    mod = 10**9 + 7

    # Handle base cases
    if n == 1:
        return str(f1 % mod)
    if n == 2:
        return str(f2 % mod)
    if n == 3:
        return str(f3 % mod)

    # For n >= 4
    def mat_mul(A, B):
        return [
            [
                (A[0][0]*B[0][0] + A[0][1]*B[1][0] + A[0][2]*B[2][0]) % mod,
                (A[0][0]*B[0][1] + A[0][1]*B[1][1] + A[0][2]*B[2][1]) % mod,
                (A[0][0]*B[0][2] + A[0][1]*B[1][2] + A[0][2]*B[2][2]) % mod
            ],
            [
                (A[1][0]*B[0][0] + A[1][1]*B[1][0] + A[1][2]*B[2][0]) % mod,
                (A[1][0]*B[0][1] + A[1][1]*B[1][1] + A[1][2]*B[2][1]) % mod,
                (A[1][0]*B[0][2] + A[1][1]*B[1][2] + A[1][2]*B[2][2]) % mod
            ],
            [
                (A[2][0]*B[0][0] + A[2][1]*B[1][0] + A[2][2]*B[2][0]) % mod,
                (A[2][0]*B[0][1] + A[2][1]*B[1][1] + A[2][2]*B[2][1]) % mod,
                (A[2][0]*B[0][2] + A[2][1]*B[1][2] + A[2][2]*B[2][2]) % mod
            ]
        ]

    # Matrix multiplication wrapper for cleaner code
    def mat_mul_fn(A, B):
        C = [[0]*(3) for _ in range(3)]
        for i in range(3):
            for j in range(3):
                for k in range(3):
                    C[i][j] = (C[i][j] + A[i][k] * B[k][j]) % mod
        return C

    # Matrix exponentiation
    def mat_pow(A, p):
        result = [[0]*3 for _ in range(3)]
        for i in range(3):
            result[i][i] = 1
        while p > 0:
            if p % 2 == 1:
                result = mat_mul_fn(result, A)
            A = mat_mul_fn(A, A)
            p //= 2
        return result

    # Tribonacci matrix
    M = [[1, 1, 1], [1, 0, 0], [0, 1, 0]]
    Mn = mat_pow(M, n - 3)

    # Get coefficients a_n, b_n, d_n
    # The initial state on March times is [a3, a2, a1] = [0, 0, 1]
    # After n-3 steps, we get [an, an-1, an-2]
    # So an = Mn[0][0]*a3 + Mn[0][1]*a2 + Mn[0][2]*a1
    #    = Mn[0][2]*1
    # Similarly for b_n, d_n with different initial conditions

    a_n = Mn[0][0]*0 + Mn[0][1]*0 + Mn[0][2]*1
    b_n = Mn[0][0]*0 + Mn[0][1]*1 + Mn[0][2]*0
    d_n = Mn[0][0]*1 + Mn[0][1]*0 + Mn[0][2]*0

    # Compute E_n mod (mod-2) for Euler's theorem
    E_n = (2 * n - 6) % (mod - 2)

    # Compute result
    result = pow(c, E_n, mod)
    result = (result * pow(f1, a_n, mod)) % mod
    result = (result * pow(f2, b_n, mod)) % mod
    result = (result * pow(f3, d_n, mod)) % mod

    return str(result)

