            count = 0
            queue = deque([i])
            visited[i] = True

            while queue:
                node = queue.popleft()
                count += 1
                for neighbor in adj[node]:
                    if not visited[neighbor]:
                        visited[neighbor] = True
                        queue.append(neighbor)
            components.append(count)

    if not components:
