        if current_sum == target:
            return count
        if current_sum > target:
            return float('inf')
        if idx == len(sorted_components):
            return float('inf')

        # Pruning: if we can't possibly reach target
        if current_sum + sum(sorted_components[idx:]) < target:
            return float('inf')

        # Option 1: Skip current component
        res1 = find_min_components(target, sorted_components, idx + 1, current_sum, count)

        # Option 2: Use current component if not already at target
        if res1 == float('inf') and current_sum + sorted_components[idx] <= target:
            res2 = find_min_components(target, sorted_components, idx + 1, 
                                      current_sum + sorted_components[idx], count + 1)
            return min(res1, res2)

        return res1

    # For each lucky number, find if achievable and minimum components
    min_roads = float('inf')

    for target in lucky_numbers:
        if target <= n:
            # Check if target can be formed
            result = find_min_components(target, components, 0, 0, 0)
            if result < float('inf'):
                roads_needed = result - 1
                min_roads = min(min_roads, roads_needed)

    if min_roads == float('inf'):
