    # Target: one string all 'a', other all 'b'
    if (all(c == 'a' for c in s) and all(c == 'b' for c in t)):
        return '0' + '\n'
    if (all(c == 'b' for c in s) and all(c == 'a' for c in t)):
        return '0' + '\n'

    # BFS to find minimum operations
    initial_s = tuple(s)
    initial_t = tuple(t)

    queue = deque([(initial_s, initial_t, [])])
    visited = {initial_s + initial_t}

    while queue:
        curr_s, curr_t, path = queue.popleft()

        sr, sc = len(curr_s), len(curr_s)

        for i in range(sr + 1):
            for j in range(sc + 1):
                if i == 0 and j == 0:
                    continue

                # Perform swap: new_s = t[:j] + s[i:], new_t = s[:i] + t[j:]
                new_s = curr_t[:j] + curr_s[i:]
                new_t = curr_s[:i] + curr_t[j:]

                new_key = new_s + new_t
                if new_key in visited:
                    continue

                visited.add(new_key)

