            """Check if x is strictly between start and end when going clockwise from start to end."""
            if start < end:
                return start < x < end
            return x > start or x < end

        def crosses(edge1, edge2):
            a1, b1 = edge1
            a2, b2 = edge2
            # Edge (a1, b1) divides the ring
            # a2 and b2 are on different sides if one is in arc and other is not
            a2_in_arc = cnt_between_start_end(a2, a1, b1)
            b2_in_arc = cnt_between_start_end(b2, a1, b1)
            return a2_in_arc != b2_in_arc

        # Build conflict graph: edges that cross cannot be on same side
        n_edges = m
        adj = [[] for _ in range(n_edges)]
        for i in range(n_edges):
            for j in range(i+1, n_edges):
                if crosses(edges[i], edges[j]):
                    adj[i].append(j)
                    adj[j].append(i)

        # 2-color the conflict graph (bipartite check)
        assignment = [-1] * n_edges  # -1=unassigned, 0=outside, 1=inside
