        g = math.gcd(x, y)

        if g == y:
            # y divides x exactly, one step to 0
            count += 1
            y = 0
        else:
            # When gcd divides y evenly, add quota
            if y % g == 0:
                count += y // g
                y = 0
            else:
                # Need to optimize: count steps to reach a multiple
                quotient = y // g
                count += quotient
                y %= g

    return str(count)


