import math

def mult_order(a, n):
    """Calculate multiplicative order of a modulo n."""
    if math.gcd(a, n) != 1:
        return -1
    if n == 1:
        return 1

    # Find smallest k where a^k ≡ 1 (mod n)
    # Since we know n | (b^n - 1), order divides n or is related
    pow_val = a % n
    for k in range(1, n + 1):
        if pow_val == 1:
            return k
        pow_val = (pow_val * a) % n
    return -1

