def exists_rotatable(n, b):
    if n == 1:
        return False

    # Calculate b^n - 1
    bn = b ** n
    mod = bn - 1

    # Get all divisors of mod
    divisors = get_divisors(mod)

    for d in divisors:
        # d must satisfy: light <= b - 1
        if d >= b:
